<div class="metric-grid"><div class="metric-card"><span>Posts</span><strong><?= (int)$counts['posts'] ?></strong><small><?= (int)$counts['published'] ?> published items total</small></div><div class="metric-card"><span>Pages</span><strong><?= (int)$counts['pages'] ?></strong><small>Structured site content</small></div><div class="metric-card"><span>Media</span><strong><?= (int)$counts['media'] ?></strong><small>Images in the library</small></div><div class="metric-card"><span>Users</span><strong><?= (int)$counts['users'] ?></strong><small>Team accounts</small></div></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Recently updated</h2><p>Latest content activity across the site.</p></div><div class="actions"><a class="btn" href="/admin/pages/create">New page</a><a class="btn primary" href="/admin/posts/create">New post</a></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Content</th><th>Type</th><th>Status</th><th>Author</th><th>Updated</th></tr></thead><tbody><?php foreach($recent as $item):?><tr><td><strong><?= e($item['title']) ?></strong></td><td><span class="badge neutral"><?= e($item['type']) ?></span></td><td><span class="badge <?= $item['status']==='published'?'success':'warning' ?>"><?= e($item['status']) ?></span></td><td><?= e($item['author_name']) ?></td><td class="muted"><?= e($item['updated_at']) ?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="5" class="empty-cell">No content yet.</td></tr><?php endif;?></tbody></table></div></section>
<aside class="panel activity-panel"><div class="panel-head"><div><h2>Activity</h2><p>Recent admin changes.</p></div><a href="/admin/activity">View all</a></div><div class="activity-list"><?php foreach($activity as $a):?><div class="activity-item"><span class="activity-dot"></span><div><strong><?= e(str_replace('.',' ',ucfirst($a['action']))) ?></strong><p><?= e($a['user_name']??'System') ?> · <?= e($a['created_at']) ?></p></div></div><?php endforeach;?><?php if(!$activity):?><p class="muted">Activity will appear here as you manage the site.</p><?php endif;?></div></aside></div>